{"title":"MiniMax联调小游戏","summary":"点击屏幕不断得分，在倒计时内挑战更高分数。","html":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
<title>MiniMax联调小游戏</title>
<style>
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;user-select:none}
html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:Arial,"PingFang SC","Microsoft YaHei",sans-serif;background:#101820;color:#fff}
#game{position:fixed;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:calc(18px + env(safe-area-inset-top)) 18px calc(20px + env(safe-area-inset-bottom));background:linear-gradient(180deg,#16222a 0%,#243b35 54%,#121712 100%)}
.top{width:100%;display:flex;justify-content:space-between;gap:12px;font-weight:700}
.panel{min-width:108px;padding:10px 12px;border:2px solid rgba(255,255,255,.16);border-radius:8px;background:rgba(0,0,0,.22);box-shadow:0 8px 20px rgba(0,0,0,.18)}
.label{font-size:12px;color:#b9d8ce;letter-spacing:0}
.value{font-size:28px;line-height:1.05;margin-top:4px}
.center{flex:1;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;position:relative}
.title{font-size:28px;font-weight:900;margin:0 0 10px;color:#f8f7e8;text-shadow:0 3px 0 rgba(0,0,0,.25)}
.hint{font-size:15px;line-height:1.5;color:#cfe7dd;margin:0 0 28px;max-width:280px}
.tapButton{width:min(64vw,260px);height:min(64vw,260px);max-height:260px;border-radius:50%;border:5px solid #f8f7e8;background:radial-gradient(circle at 35% 28%,#ffef8a 0%,#ffd447 34%,#f05d3a 72%,#b8322a 100%);box-shadow:0 18px 0 #781f1d,0 26px 36px rgba(0,0,0,.38),inset 0 8px 18px rgba(255,255,255,.45);display:flex;align-items:center;justify-content:center;font-size:34px;font-weight:900;color:#fff;text-shadow:0 3px 0 rgba(0,0,0,.3);transition:transform .06s ease,box-shadow .06s ease}
.tapButton:active,.tapButton.down{transform:translateY(10px) scale(.98);box-shadow:0 8px 0 #781f1d,0 16px 24px rgba(0,0,0,.34),inset 0 6px 16px rgba(255,255,255,.4)}
.combo{height:30px;margin-top:24px;font-size:22px;font-weight:900;color:#ffef8a;text-shadow:0 2px 0 rgba(0,0,0,.35);opacity:0;transform:translateY(8px);transition:.12s}
.combo.show{opacity:1;transform:translateY(0)}
.bottom{width:100%;display:flex;justify-content:center}
.action{appearance:none;border:0;border-radius:8px;padding:13px 22px;background:#f8f7e8;color:#16222a;font-size:16px;font-weight:900;box-shadow:0 6px 0 #a9a67f}
.action:active{transform:translateY(4px);box-shadow:0 2px 0 #a9a67f}
.float{position:absolute;font-weight:900;color:#ffef8a;text-shadow:0 2px 0 rgba(0,0,0,.35);pointer-events:none;animation:rise .55s ease-out forwards}
@keyframes rise{from{opacity:1;transform:translate(-50%,0) scale(1)}to{opacity:0;transform:translate(-50%,-70px) scale(1.35)}}
.overlay{position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:24px;background:rgba(10,15,18,.72)}
.dialog{width:min(88vw,340px);border-radius:8px;background:#f8f7e8;color:#16222a;padding:24px;text-align:center;box-shadow:0 22px 50px rgba(0,0,0,.38)}
.dialog h2{margin:0 0 10px;font-size:26px}.dialog p{margin:8px 0 18px;font-size:16px;line-height:1.5}.big{font-size:46px;font-weight:900;color:#f05d3a}.dialog .action{background:#16222a;color:#fff;box-shadow:0 6px 0 #0a0f12;width:100%}
</style>
</head>
<body>
<main id="game">
  <section class="top">
    <div class="panel"><div class="label">分数</div><div id="score" class="value">0</div></div>
    <div class="panel"><div class="label">时间</div><div id="time" class="value">30</div></div>
  </section>
  <section class="center" id="playArea">
    <h1 class="title">MiniMax联调小游戏</h1>
    <p class="hint">点击大按钮得分，连续快速点击会触发连击加分。</p>
    <button id="tapButton" class="tapButton" type="button">点击</button>
    <div id="combo" class="combo">连击 +1</div>
  </section>
  <section class="bottom"><button id="start" class="action" type="button">开始游戏</button></section>
</main>
<div id="overlay" class="overlay">
  <div class="dialog">
    <h2>时间到</h2>
    <p>本局得分</p>
    <div id="finalScore" class="big">0</div>
    <p id="rankText">再来一局刷新纪录。</p>
    <button id="restart" class="action" type="button">再玩一次</button>
  </div>
</div>
<script>
(function(){
  var score=0,time=30,playing=false,timer=null,lastTap=0,combo=0,best=Number(localStorage.getItem('minimax_click_best')||0);
  var scoreEl=document.getElementById('score'),timeEl=document.getElementById('time'),tapBtn=document.getElementById('tapButton'),startBtn=document.getElementById('start'),overlay=document.getElementById('overlay'),finalScore=document.getElementById('finalScore'),rankText=document.getElementById('rankText'),comboEl=document.getElementById('combo'),playArea=document.getElementById('playArea');
  function render(){scoreEl.textContent=score;timeEl.textContent=time;}
  function startGame(){score=0;time=30;combo=0;lastTap=0;playing=true;overlay.style.display='none';startBtn.textContent='重新开始';render();clearInterval(timer);timer=setInterval(function(){time--;render();if(time<=0)endGame();},1000);}
  function endGame(){playing=false;clearInterval(timer);finalScore.textContent=score;if(score>best){best=score;localStorage.setItem('minimax_click_best',best);rankText.textContent='新纪录：'+best+' 分';}else{rankText.textContent='最高纪录：'+best+' 分';}overlay.style.display='flex';}
  function pop(x,y,text){var f=document.createElement('div');f.className='float';f.textContent=text;f.style.left=x+'px';f.style.top=y+'px';playArea.appendChild(f);setTimeout(function(){f.remove();},600);}
  function tap(e){if(!playing)startGame();var now=Date.now();combo=(now-lastTap<420)?combo+1:1;lastTap=now;var add=combo>=8?3:(combo>=4?2:1);score+=add;render();comboEl.textContent='连击 x'+combo+'  +'+add;comboEl.classList.add('show');clearTimeout(comboEl._t);comboEl._t=setTimeout(function(){comboEl.classList.remove('show');},350);var p=e.touches?e.touches[0]:e;pop(p.clientX,p.clientY,'+'+add);tapBtn.classList.add('down');setTimeout(function(){tapBtn.classList.remove('down');},70);}
  tapBtn.addEventListener('pointerdown',tap);
  startBtn.addEventListener('click',startGame);
  document.getElementById('restart').addEventListener('click',startGame);
  document.addEventListener('touchmove',function(e){e.preventDefault();},{passive:false});
  render();
})();
</script>
</body>
</html>"}

